choose.when:
SELECT COUNT(*) FROM metadata_table


        AND table_name LIKE CONCAT('%', #{tableName}, '%')


        AND business_code = #{businessCode}

SELECT * FROM metadata_table


        AND table_name LIKE CONCAT('%', #{tableName}, '%')


        AND business_code = #{businessCode}


ORDER BY create_time DESC
LIMIT #{pageRequest.offset}, #{pageRequest.size}

choose.otherwise:
SELECT t.* FROM metadata_table t INNER JOIN metadata_business_system bs ON t.business_code = bs.business_code LEFT JOIN metadata_physical_database pdb ON ( NULLIF(TRIM(COALESCE(NULLIF(TRIM(t.database_name), ''), NULLIF(TRIM(bs.database_name), ''))), '') IS NOT NULL AND LOWER(TRIM(pdb.catalog_name)) = LOWER(TRIM(COALESCE(NULLIF(TRIM(t.database_name), ''), NULLIF(TRIM(bs.database_name), '')))) )
bs.is_enabled = 1 AND t.is_enabled = 1 AND (pdb.id IS NULL OR pdb.is_enabled = 1)
AND t.table_name LIKE CONCAT('%', #{tableName}, '%')
AND t.business_code = #{businessCode}
ORDER BY t.create_time DESC LIMIT #{pageRequest.offset}, #{pageRequest.size}

mapper.select:
SELECT t.* FROM metadata_table t INNER JOIN metadata_module_table mt ON t.table_code = mt.table_code INNER JOIN metadata_business_system bs ON t.business_code = bs.business_code LEFT JOIN metadata_physical_database pdb ON ( NULLIF(TRIM(COALESCE(NULLIF(TRIM(t.database_name), ''), NULLIF(TRIM(bs.database_name), ''))), '') IS NOT NULL AND LOWER(TRIM(pdb.catalog_name)) = LOWER(TRIM(COALESCE(NULLIF(TRIM(t.database_name), ''), NULLIF(TRIM(bs.database_name), '')))) ) WHERE t.is_enabled = 1 AND bs.is_enabled = 1 AND (pdb.id IS NULL OR pdb.is_enabled = 1) AND mt.module_code = #{moduleCode}
AND t.business_code = #{businessCode}
ORDER BY t.create_time DESC

